import json,pathlib
p=pathlib.Path(__file__).parent
g=json.loads((p/'dag.json').read_text()); d={n['id']:n for n in g['nodes']}
A='https://www.anthropic.com/research/demystifying-evals-for-ai-agents'
R='https://developers.openai.com/cookbook/examples/realtime_eval_guide'
B='https://developers.openai.com/api/docs/guides/evaluation-best-practices'
def ev(url,loc,claim):return {'url':url,'locator':loc,'claim':claim,'access':'Opened relevant primary-source HTML passages during this run'}
def update(i,a,es=[],status='supported'):
 d[i]['answer']=a;d[i]['status']=status;d[i]['evidence']+=es
update('system','The model is the text-generating component called through an API. The application also supplies instructions (a prompt), contextual information and sometimes callable functions (tools). Evaluate the behavior of this combination on its intended task, not a model’s general ranking.',[ev(B,'Identify where you need evals > Single-turn model interactions; Workflow architectures; Single-agent architectures, lines 1063–1105','Instructions, model calls, fetched information and callable tools participate in application behavior.')])
update('intent','Acceptable behavior means meeting requirements for the chosen support task. Specify each criterion as an observable question. Constructed examples: Is the policy answer accurate? Does the assistant request missing information instead of inventing it? Does it escalate when the stated policy requires that? Keep these separate from tone. Actual company rules must come from its owner.',[ev(R,'4.1 Start with a gold seed set; 4.2 Build for iteration, lines 1044–1055','Cover core tasks, escalation and refusal, with positive and negative examples.')])
update('reference','For each case, store the input, relevant policy or order facts, and expert-reviewed expectations. A category task can have one correct label. An answer task can instead list required facts and forbidden claims while allowing many phrasings. The reference is the information used to judge the answer; it is not automatically a script the assistant must reproduce.')
update('outcome','Observe the full conversation, tool calls and resulting system state. An assistant saying a refund succeeded does not prove it occurred. Check communication quality separately from actual resolution.',[ev(A,'The structure of an evaluation, lines 60–68; Evaluating conversational agents, lines 219–257','Transcripts and outcomes provide different evidence.')])
update('run','Use a Python loop to load each case, call the application with its specified inputs, and save its response and any relevant conversation or action results. Record which prompt, model, settings, policy context and grader version were used. This is one run; keeping the inputs and rules reusable makes later runs comparable.')
update('grade','A grader applies a rule to an output and the case’s reference information. Code can compare exact category labels or check structured values. A human or model can assess a rubric: explicit criteria such as factual accuracy against supplied policy. Matching wording, resembling a reference and meeting a requirement are different judgments. Use the rule that measures the intended criterion.')
update('summary','For a binary criterion, pass rate = passing judged cases / all judged cases. Constructed example: 16 passes among 20 judged cases is 80%, not a probability guarantee for every future customer. State the denominator, criteria, dataset and run configuration. Keep unjudged or errored cases visible rather than silently counting them as successes. The score describes the tested behavior; its relevance depends on the cases and grading.')
update('compare','Run the original and changed application on the same version of cases and grading criteria. Compare per-case changes and subgroup results, repeat trials to see variability, and check fresh held-out cases. A small difference alone does not establish reliable improvement. Formal uncertainty estimation for close comparisons is outside this starter graph; no statistical significance claim is made.')
update('start','Constructed starter plan: choose policy-question answering. Save a small reviewed case collection with id, question, policy excerpt, required facts, forbidden claims and scenario tag. Include ordinary answers, missing details and escalation cases. Run the application, manually grade policy accuracy and required behavior, and compute pass counts by criterion. Inspect failures; automate only checks that agree with expert review. Change one component, rerun, and inspect regressions. Add multi-turn or tool-outcome cases if those capabilities are in scope.',[ev(B,'Design your eval process, lines 1012–1019','Objective, examples, grading, comparison and continued evaluation form the core process.')])
update('target','Evals provide repeatable evidence about whether an application meets explicit needs across relevant cases despite variable outputs. Cases exercise the application; graders compare observed behavior with expectations; results reveal failures and help compare changes. Begin with one support task and a small expert-reviewed dataset, then expand with observed failures. Scores support scoped decisions, not unrestricted claims of reliability.')
# Synthesis nodes use the relevant conceptual evidence rather than an invented source for the constructed example.
d['compare']['evidence']=[ev(R,'4.2 Build for iteration; 4.3 Expand from production failures; 6) Eval Harness, lines 1049–1078, 1108–1113','Consistent tests, controlled changes and withheld examples improve comparisons.'),ev(A,'The structure of an evaluation, lines 61–62','Multiple trials address variable outputs.')]
d['target']['evidence']=d['variation']['evidence']+d['start']['evidence']
def add(i,q,a,es):
 n={'id':i,'question':q,'answer':a,'status':'supported','evidence':es};g['nodes'].append(n);d[i]=n
add('repeat','Why run the same case more than once?','A trial is one attempt at a case. Repeated attempts reveal inconsistent success that a single run hides. Report attempts and failures; repetitions do not add new kinds of customer situations.',[ev(A,'The structure of an evaluation, lines 61–62; How to think about non-determinism, lines 271–273','Repeating attempts reveals variation.')])
add('holdout','Why keep some cases out of day-to-day tuning?','Repeatedly editing a prompt to fit familiar cases can improve their scores without improving new cases. Keep some cases unused during tuning and check them occasionally. If they start guiding edits, replenish the untouched set.',[ev(R,'4.3 Expand from production failures, lines 1062–1078','Untouched cases help detect overfitting to the development benchmark.')])
add('slices','Why inspect groups of cases instead of only the overall score?','Tag scenarios so a total can be separated into relevant groups. Constructed example: 18 routine successes can hide two escalation failures in an overall 18/20 result. Show each group’s denominator and failure examples; a tiny group provides limited evidence.',[ev(R,'4.2 Build for iteration, lines 1054–1060','Balanced examples and tags allow finer-grained diagnosis.')])
# Replace bundled/reading-order dependencies with concept dependencies.
g['edges']=[e for e in g['edges'] if (e['from'],e['to']) not in {('variation','compare'),('outcome','start')}]
def edge(f,t,w):g['edges'].append({'from':f,'to':t,'why':w})
for f,t,w in [
('outcome','run','Knowing the observable behavior determines which outputs and effects a run must record.'),
('variation','repeat','Repeated attempts matter because identical inputs can yield different outputs.'),
('run','repeat','A trial repeats the defined execution of a case.'),
('repeat','compare','Score differences must be interpreted alongside within-case variability.'),
('cases','holdout','Withholding cases requires understanding the test collection and its coverage.'),
('holdout','compare','Unused examples check whether gains extend beyond the examples used to tune.'),
('summary','slices','Subgroup rates partition the same numerator and denominator used by the overall rate.'),
('slices','compare','An overall gain can conceal worsening behavior in a required support scenario.'),
('calibrate','start','Automating the starter workflow requires checking that judgments match expert expectations.')]:edge(f,t,w)
g['revisions'].append({'round':1,'phase':'Supplemental primary-source research and graph revision','gaps':['Support outcomes beyond final-answer wording','Repeated trials and untouched cases','Subgroup failures hidden by aggregate scores'],'searches':['site.anthropic.com engineering demystifying evals for ai agents customer support outcome transcript trials','site.developers.openai.com evaluation best practices holdout dataset uncertainty continuous evaluation'],'evidence':[{'url':A,'locators':['The structure of an evaluation','Evaluating conversational agents','How to think about non-determinism in evaluations for agents']},{'url':R,'locators':['4.1–4.3 Data: building a benchmark','6) Eval Harness']},{'url':B,'locators':['What are evals? through Design your eval process','Identify where you need evals']}],'changes':['Clarified model, prompt and tool meanings using the reader’s API knowledge.','Added repeat, holdout and slices nodes, replacing a bundled variability-to-comparison edge.','Made outcome evidence a prerequisite for what the run records.','Filled support criteria and starter plan with explicitly constructed examples.','Added per-criterion denominator interpretation; retained a formal uncertainty-method limit.','Every retained node reaches target; no source-heading nodes were added.']})
g['scope_limits']=['No actual company policy, support logs or application provided; company-specific criteria require owner validation.','No API calls or measured application performance; all numerical examples and starter records are constructed.','No statistical significance, sample-size guarantee or confidence interval method supplied for close-score decisions.','Legacy Evals API tutorial is conceptual evidence only, not implementation guidance.','Graph-only delivery: exhibits and rendered view belong to the shared renderer; no report or interactive view produced.']
g['completion_status']='Complete for requested conceptual prerequisite graph; operational and statistical limits disclosed.'
(p/'dag.json').write_text(json.dumps(g,indent=2,ensure_ascii=False)+'\n')
